const $ = id => document.getElementById(id);
const COLORS = ['#2563eb','#0f766e','#7c3aed','#d97706','#475569','#059669','#0891b2','#4f46e5','#65a30d','#92400e'];
const SECTORS = [
 ['الزراعة','agriculture'],['البنوك','banks'],['البتروكيماويات','petrochem'],['النفط و الغاز','oilgas'],['الاسمنت','cement'],['تجارة و تجزئة','retail'],['الأغذية والمشروبات','food'],['الصناعات التحويلية','industrial'],['العقارات','realestate'],['النقل','transport'],['الاتصالات','telecom'],['الرعاية الصحية','health'],['خدمات الرعاية الصحية','healthservices'],['التعليم و التدريب','education'],['تقنية المعلومات','information-technology'],['المواد الاساسية','materials'],['التعدين والمعادن','mining'],['المراكز الرياضية','sports'],['موردي الادوية','pharma'],['الفنادق و السياحة','hotels-tourism'],['وسائل الاعلام','media'],['متعددة الأنشطة','multi'],['المرافق والطاقة','utilities'],['خدمات الاعمال','business-services'],['المنتجات الزجاجية','glass'],['أسواق الاوراق المالية','exchange'],['السلع الاستهلاكية','consumer']
];
const LABELS = { revenue:'الإيرادات',grossIncome:'إجمالي الدخل',operatingIncome:'دخل العمليات',netProfit:'صافي الربح',epsBeforeExceptional:'ربح السهم قبل البنود الاستثنائية',eps:'ربح السهم',grossMargin:'هامش إجمالي الربح',operatingMargin:'هامش دخل العمليات',netMargin:'هامش صافي الربح',assets:'الموجودات',financing:'التمويل / صافي القروض',deposits:'ودائع العملاء',equity:'حقوق المساهمين',netFinancingIncome:'صافي الدخل من التمويل والاستثمار',loansToDeposits:'نسبة القروض إلى الودائع',returnOnEquity:'العائد على حقوق المساهمين',retailFinancingShare:'نسبة تمويل الأفراد',corporateFinancingShare:'نسبة تمويل الشركات',internationalFinancingShare:'نسبة التمويل الدولي',pe:'مكرر الأرباح التاريخي',dilutedEps:'ربح السهم المخفض',recurringEps:'ربحية السهم المتكررة',provisions:'المخصصات',averageShares:'متوسط عدد الأسهم'};
const metricOrder = ['revenue','grossIncome','operatingIncome','netProfit','netFinancingIncome','assets','financing','deposits','equity','epsBeforeExceptional','eps','dilutedEps','recurringEps','grossMargin','operatingMargin','netMargin','loansToDeposits','returnOnEquity','retailFinancingShare','corporateFinancingShare','internationalFinancingShare','pe','provisions','averageShares'];
const fmt = new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let dataset, companies=[], years=[], selectedYears=[], selectedMetric='netProfit', selectedSymbols=[];
const records = company => new Map((company.years||[]).map(record=>[record.year,record.values||{}]));
const valueAt = (company,year) => records(company).get(year)?.[selectedMetric] ?? null;
const companyColor = company => COLORS[companies.indexOf(company)%COLORS.length];
const unit = key => key.endsWith('Margin') || key.endsWith('Share') || key === 'loansToDeposits' || key === 'returnOnEquity' ? '%' : key==='eps'||key==='epsBeforeExceptional'||key==='dilutedEps'||key==='recurringEps' ? 'ريال' : key==='pe' ? 'مرة' : key==='averageShares' ? 'مليون سهم' : 'مليون ريال';
const display = value => value == null || !Number.isFinite(value) ? '—' : `${fmt.format(unit(selectedMetric)==='%' ? value*100 : value)}${unit(selectedMetric)==='%'?'%':''}`;
function getCompanies(data){ return data.companies || data.banks || []; }
function updateMetricOptions(){
 const keys = [...new Set(companies.flatMap(c => (c.years||[]).flatMap(r => Object.keys(r.values||{}))))];
 const ordered = metricOrder.filter(key=>keys.includes(key)).concat(keys.filter(key=>!metricOrder.includes(key)));
 if(!ordered.includes(selectedMetric)) selectedMetric=ordered.includes('netProfit')?'netProfit':ordered[0];
 $('metric-select').innerHTML=ordered.map(key=>`<option value="${esc(key)}"${key===selectedMetric?' selected':''}>${esc(LABELS[key]||key)}</option>`).join('');
}
function renderCompanies(){ $('company-options').innerHTML=companies.map((c,i)=>`<label class="company-option"><input type="checkbox" value="${esc(c.symbol)}" ${selectedSymbols.includes(c.symbol)?'checked':''}><i style="--company-color:${COLORS[i%COLORS.length]}"></i><span>${esc(c.name)} <bdi>${esc(c.symbol)}</bdi></span></label>`).join(''); $('selection-count').textContent=`(${selectedSymbols.length} من ${companies.length})`; }
function renderYears(){ $('year-options').innerHTML=years.map(year=>`<label class="year-option"><input type="checkbox" value="${year}" ${selectedYears.includes(year)?'checked':''}><bdi>${year}</bdi></label>`).join(''); }
function sortByValue(a,b,year){ const av=valueAt(a,year),bv=valueAt(b,year); if(av==null&&bv==null)return a.symbol.localeCompare(b.symbol,'en'); if(av==null)return 1; if(bv==null)return -1; return bv-av || a.symbol.localeCompare(b.symbol,'en'); }
function renderTable(chosen){
 const latestYear=selectedYears.at(-1), ordered=[...chosen].sort((a,b)=>sortByValue(a,b,latestYear));
 $('comparison-table').innerHTML=`<caption>${esc(LABELS[selectedMetric]||selectedMetric)} · مقارنة سنوية · ${esc(unit(selectedMetric))} · ترتيب الشركات حسب ${latestYear}</caption><thead><tr><th>السنة</th>${ordered.map(c=>`<th><span class="company-header"><i style="--company-color:${companyColor(c)}"></i>${esc(c.name)} <bdi>${esc(c.symbol)}</bdi></span></th>`).join('')}</tr></thead><tbody>${selectedYears.map(y=>`<tr><th><bdi>${y}</bdi></th>${ordered.map(c=>{const v=valueAt(c,y);return `<td class="${v==null?'is-missing':v<0?'negative-value':''}">${display(v)}</td>`}).join('')}</tr>`).join('')}</tbody>`;
}
function renderBars(chosen){
 const vals=chosen.flatMap(c=>selectedYears.map(y=>valueAt(c,y))).filter(v=>Number.isFinite(v)); const maxAbs=Math.max(1,...vals.map(v=>Math.abs(v)));
 const groups=selectedYears.map(y=>{ const ordered=[...chosen].sort((a,b)=>sortByValue(a,b,y)); return `<div class="bar-group"><div class="plot-area"><div class="zero-line"></div>${ordered.map(c=>{const color=companyColor(c),v=valueAt(c,y); if(v==null)return `<div class="bar-slot"><span class="bar-missing">—</span></div>`; const h=Math.max(2,Math.abs(v)/maxAbs*46); const cls=v>=0?'positive':'negative'; const labelStyle=cls==='positive'?`bottom:calc(50% + ${h}%);`:`top:calc(50% + ${h}%);`; const barStyle=cls==='positive'?`height:${h}%;bottom:50%;`:`height:${h}%;top:50%;`; return `<div class="bar-slot"><span class="bar-value ${cls}" style="${labelStyle}">${esc(display(v))}</span><div class="bar ${cls}" style="${barStyle}--company-color:${color}" title="${esc(c.name)} · ${y}: ${esc(display(v))}"></div></div>`}).join('')}</div><bdi>${y}</bdi></div>`; }).join('');
 $('comparison-bars').innerHTML=`<div class="bars-title"><h3>المقارنة بالأعمدة</h3><span>${esc(LABELS[selectedMetric]||selectedMetric)} · ${esc(unit(selectedMetric))}</span></div><div class="bar-legend">${chosen.map(c=>`<span><i style="--company-color:${companyColor(c)}"></i>${esc(c.name)}</span>`).join('')}</div><div class="bar-chart" style="grid-template-columns:repeat(${selectedYears.length},minmax(0,1fr))">${groups}</div><div class="bar-axis-note">ترتيب الأعمدة داخل كل سنة تنازليًا من الأعلى إلى الأقل. مساحة الرسم تتوسع تلقائيًا حسب عدد السنوات المختارة. لكل شركة لون ثابت.</div>`;
}
function render(){ renderCompanies(); renderYears(); const chosen=companies.filter(c=>selectedSymbols.includes(c.symbol)); if(chosen.length<2){$('comparison-status').textContent='اختر شركتين على الأقل لعرض المقارنة.';$('comparison-table').innerHTML='';$('comparison-bars').innerHTML='';return;} if(selectedYears.length<1){$('comparison-status').textContent='اختر سنة واحدة على الأقل لعرض المقارنة.';$('comparison-table').innerHTML='';$('comparison-bars').innerHTML='';return;} $('comparison-status').textContent=`مقارنة ${LABELS[selectedMetric]||selectedMetric} بين ${chosen.length} شركات خلال ${selectedYears[0]}–${selectedYears.at(-1)}. الأعمدة مرتبة تلقائيًا من الأعلى إلى الأقل داخل كل سنة.`; renderTable(chosen);renderBars(chosen); }
async function loadSector(slug,initial=false){ const response=await fetch(`${slug==='banks'?'banks-financials':slug+'-financials'}.json?v=comparison-v2`); dataset=await response.json(); companies=getCompanies(dataset); years=dataset.years||[]; selectedYears=[...years]; $('period-badge').innerHTML=`السنوات المتاحة<br><bdi>${years[0]}–${years.at(-1)}</bdi>`; updateMetricOptions(); selectedSymbols=companies.slice(0,Math.min(3,companies.length)).map(c=>c.symbol); render(); }
$('sector-select').innerHTML=SECTORS.map(([label,slug])=>`<option value="${slug}"${slug==='agriculture'?' selected':''}>${esc(label)}</option>`).join('');
$('sector-select').addEventListener('change',e=>loadSector(e.target.value)); $('metric-select').addEventListener('change',e=>{selectedMetric=e.target.value;render();}); $('company-options').addEventListener('change',e=>{if(!e.target.matches('input'))return;const next=[...$('company-options').querySelectorAll('input:checked')].map(i=>i.value);if(next.length>=2)selectedSymbols=next;else e.target.checked=true;render();}); $('year-options').addEventListener('change',e=>{if(!e.target.matches('input'))return;const next=[...$('year-options').querySelectorAll('input:checked')].map(i=>Number(i.value)).sort((a,b)=>a-b);if(next.length>=1)selectedYears=next;else e.target.checked=true;render();});
loadSector('agriculture',true).catch(e=>{$('comparison-status').textContent='تعذر تحميل بيانات القطاع.';console.error(e);});
